Author: Alan T. DeKok <aland@freeradius.org>
Date:   Wed Oct 6 16:47:21 2021 -0400

    check for overflow before decoding anything
---
 src/protocols/tacacs/decode.c | 26 +++++++++++++++++---------
 1 file changed, 17 insertions(+), 9 deletions(-)

diff --git a/src/protocols/tacacs/decode.c b/src/protocols/tacacs/decode.c
index 26488c5327..4d0c4997c3 100644
--- a/src/protocols/tacacs/decode.c
+++ b/src/protocols/tacacs/decode.c
@@ -91,7 +91,21 @@ static int tacacs_decode_args(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_att
        }

        /*
-        *      Then, do the dirty job...
+        *      Check for malformed packets before anything else.
+        */
+       for (i = 0; i < arg_cnt; i++) {
+               if ((p + arg_list[i]) > end) {
+                       fr_strerror_printf("'%s' argument %u length %u overflows the remaining data (%zu) in the packet",
+                                          parent->name, i, arg_list[i], end - p);
+                       return -1;
+               }
+
+               p += arg_list[i];
+       }
+       p = *data;
+
+       /*
+        *      Then, do the dirty job of creating attributes.
         */
        for (i = 0; i < arg_cnt; i++) {
                uint8_t const *value, *name_end, *arg_end;
@@ -100,12 +114,6 @@ static int tacacs_decode_args(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_att

                if (arg_list[i] < 2) goto next; /* skip malformed */

-               if (p + arg_list[i] > end) {
-                       fr_strerror_printf("'%s' argument %u length %u overflows the remaining data in the packet",
-                                          parent->name, i, arg_list[i]);
-                       return -1;
-               }
-
                memcpy(buffer, p, arg_list[i]);
                buffer[arg_list[i]] = '\0';

@@ -186,8 +194,8 @@ static int tacacs_decode_field(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_at
        fr_pair_t *vp;

        if ((p + field_len) > end) {
-               fr_strerror_printf("'%s' length %u overflows the remaining data in the packet",
-                                  da->name, field_len);
+               fr_strerror_printf("'%s' length %u overflows the remaining data (%zu) in the packet",
+                                  da->name, field_len, p - end);
                return -1;
        }

commit a6328e9ff7b01940d01abc2844a878ea57cf26cc
Author: Alan T. DeKok <aland@freeradius.org>
Date:   Mon Feb 13 15:41:06 2023 -0500

    be clearer about checking argc for overflows.

    Should fix the fuzzer issues.
---
 src/protocols/tacacs/decode.c | 8 ++------
 1 file changed, 2 insertions(+), 6 deletions(-)

diff --git a/src/protocols/tacacs/decode.c b/src/protocols/tacacs/decode.c
index 678e4ecc8e..c3b3915996 100644
--- a/src/protocols/tacacs/decode.c
+++ b/src/protocols/tacacs/decode.c
@@ -134,12 +134,11 @@ int fr_tacacs_packet_to_code(fr_tacacs_packet_t const *pkt)
 } while (0)

 #define ARG_COUNT_CHECK(_msg, _hdr) do { \
-       if ((p + _hdr.arg_cnt) > end) { \
+       fr_assert(p == (uint8_t const *) &(_hdr)); \
+       if ((p + data_len) > end) { \
                fr_strerror_printf("Argument count %u overflows the remaining data (%zu) in the %s packet", _hdr.arg_cnt, end - p, _msg); \
                goto fail; \
        } \
-       p += _hdr.arg_cnt; \
-       data_len = 0; \
        for (int i = 0; i < _hdr.arg_cnt; i++) { \
                data_len += _hdr.arg_len[i]; \
                if (data_len > (size_t) (end - p)) { \
@@ -764,7 +763,6 @@ ssize_t fr_tacacs_decode(TALLOC_CTX *ctx, fr_pair_list_t *out, uint8_t const *bu
                        if (data_len > (size_t) (end - p)) goto overflow;
                        /* can't check for underflow, as we have argv[argc] */

-                       p = BODY(author_req);
                        ARG_COUNT_CHECK("Authorization-Request", pkt->author_req);
                        DECODE_FIELD_UINT8(attr_tacacs_packet_body_type, FR_PACKET_BODY_TYPE_REQUEST);

@@ -823,7 +821,6 @@ ssize_t fr_tacacs_decode(TALLOC_CTX *ctx, fr_pair_list_t *out, uint8_t const *bu
                        if (data_len > (size_t) (end - p)) goto overflow;
                        /* can't check for underflow, as we have argv[argc] */

-                       p = BODY(author_reply);
                        ARG_COUNT_CHECK("Authorization-Reply", pkt->author_reply);
                        DECODE_FIELD_UINT8(attr_tacacs_packet_body_type, FR_PACKET_BODY_TYPE_RESPONSE);

@@ -886,7 +883,6 @@ ssize_t fr_tacacs_decode(TALLOC_CTX *ctx, fr_pair_list_t *out, uint8_t const *bu
                        if (data_len > (size_t) (end - p)) goto overflow;
                        /* can't check for underflow, as we have argv[argc] */

-                       p = BODY(acct_req);
                        ARG_COUNT_CHECK("Accounting-Request", pkt->acct_req);
                        DECODE_FIELD_UINT8(attr_tacacs_packet_body_type, FR_PACKET_BODY_TYPE_REQUEST);
